import rclpy
from rclpy.node import Node
from rcl_interfaces.msg import Log
import os
import datetime

class RosLogAnalyser(Node):
    """订阅 /rosout 话题并将日志消息保存到本地文件"""

    def __init__(self):
        super().__init__('ros_log_analyser')

        # 日志存放目录
        self.log_dir = os.path.expanduser("/home/ubuntu/XARM_logs")
        os.makedirs(self.log_dir, exist_ok=True)

        # 日志文件名，带时间戳
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        self.log_file_path = os.path.join(self.log_dir, f"rosout_{timestamp}.log")

        # 软连接，方便找到最新日志
        last_link = os.path.join(self.log_dir, "last_rosout.log")
        try:
            if os.path.islink(last_link) or os.path.exists(last_link):
                os.remove(last_link)
            os.symlink(self.log_file_path, last_link)
            self.get_logger().info(f'已创建软连接: {last_link} -> {self.log_file_path}')
        except Exception as e:
            self.get_logger().warn(f'创建软连接失败: {e}')

        with open(self.log_file_path, 'a', encoding='utf-8') as f:
            f.write(f'RosLogAnalyser 节点已启动，正在监听 /rosout\n')

        self.subscription = self.create_subscription(
            Log,
            '/rosout',
            self.log_callback,
            100
        )
        self.get_logger().info(f'RosLogAnalyser 节点已启动，正在监听 /rosout 话题')
        self.get_logger().info(f'ROS日志文件保存位置: {self.log_file_path}')

    def log_callback(self, msg: Log):
        # 拼接格式化时间
        # Log.msg.header.stamp 为 builtin_interfaces/Time
        stamp = msg.stamp
        t_str = f"{stamp.sec}.{stamp.nanosec:09d}"
        contains_xarm = "XARM/src" in msg.file if msg.file else False
        # PREFIX: [时间] [LEVEL] [NODE] [文件:行号] [功能] 消息内容
        file_line = f"{msg.file}:{msg.line}" if msg.file and msg.line else ""
        func = msg.function if msg.function else ""
        # 定义ROS2日志级别对应关系
        level_map = {
            10: "DEBUG",
            20: "INFO",
            30: "WARN",
            40: "ERROR",
            50: "FATAL"
        }
        level_str = level_map.get(msg.level, str(msg.level))
        format_str = (
            f"[{t_str}] [{level_str}] [{msg.name}] "
            f"{msg.msg}"
        )

        # 写入文件
        if contains_xarm:
            with open(self.log_file_path, 'a', encoding='utf-8') as f:
                f.write(format_str + '\n')


def main(args=None):
    rclpy.init(args=args)
    node = RosLogAnalyser()
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        # launch/system 可能已经触发过 shutdown，这里避免重复调用
        if rclpy.ok():
            rclpy.shutdown()

if __name__ == '__main__':
    main()
